import { MakeLogicType, actions, kea, path, reducers } from 'kea'
import { actionToUrl, urlToAction } from 'kea-router'

import { urls } from 'scenes/urls'

export const WAREHOUSE_PROPERTIES_SCENE_TABS = ['persons', 'groups'] as const
export type WarehousePropertiesSceneTab = (typeof WAREHOUSE_PROPERTIES_SCENE_TABS)[number]
export const DEFAULT_WAREHOUSE_PROPERTIES_SCENE_TAB: WarehousePropertiesSceneTab = 'persons'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehousePropertiesSceneLogicValues {
    currentTab: WarehousePropertiesSceneTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface warehousePropertiesSceneLogicActions {
    _setCurrentTab: (tab: WarehousePropertiesSceneTab) => {
        tab: 'groups' | 'persons'
    }
    setCurrentTab: (tab: WarehousePropertiesSceneTab) => {
        tab: 'groups' | 'persons'
    }
}

export type warehousePropertiesSceneLogicType = MakeLogicType<
    warehousePropertiesSceneLogicValues,
    warehousePropertiesSceneLogicActions
>

export const warehousePropertiesSceneLogic = kea<warehousePropertiesSceneLogicType>([
    path(['products', 'customer_analytics', 'scenes', 'WarehousePropertiesScene', 'warehousePropertiesSceneLogic']),
    actions({
        setCurrentTab: (tab: WarehousePropertiesSceneTab) => ({ tab }),
        // Mirrors setCurrentTab without writing back to the URL, so urlToAction can't loop.
        _setCurrentTab: (tab: WarehousePropertiesSceneTab) => ({ tab }),
    }),
    reducers({
        currentTab: [
            DEFAULT_WAREHOUSE_PROPERTIES_SCENE_TAB as WarehousePropertiesSceneTab,
            {
                setCurrentTab: (_, { tab }) => tab,
                _setCurrentTab: (_, { tab }) => tab,
            },
        ],
    }),
    actionToUrl(() => ({
        setCurrentTab: ({ tab }) =>
            urls.warehouseProperties(tab === DEFAULT_WAREHOUSE_PROPERTIES_SCENE_TAB ? undefined : tab),
    })),
    urlToAction(({ actions, values }) => ({
        [urls.warehouseProperties()]: () => {
            if (values.currentTab !== DEFAULT_WAREHOUSE_PROPERTIES_SCENE_TAB) {
                actions._setCurrentTab(DEFAULT_WAREHOUSE_PROPERTIES_SCENE_TAB)
            }
        },
        [urls.warehouseProperties('groups')]: () => {
            if (values.currentTab !== 'groups') {
                actions._setCurrentTab('groups')
            }
        },
    })),
])
